// 1. Lấy dữ liệu từ các node trước
const fetchGold = $('Fetch Gold Price').first().json;
const sheetInput = $('Read Investment History').first().json;

const rawRates = fetchGold.rates || {};

// Giá vàng hiện tại (VND/ounce)
const goldPriceVND = rawRates.VNDXAU || rawRates.VND || 120000000;

// 2. Tính Tỷ giá USD/VND động từ API
let exchangeRateUSD = 25400; // Fallback an toàn

if (rawRates.USDVND && rawRates.USDVND > 0) {
  exchangeRateUSD = rawRates.USDVND;
} else if (rawRates.VNDUSD && rawRates.VNDUSD > 0) {
  // Nếu API trả về VNDUSD (ví dụ 0.00003937), đảo ngược lại thành USD/VND (1 / 0.00003937 ≈ 25400)
  exchangeRateUSD = rawRates.VNDUSD < 1 ? 1 / rawRates.VNDUSD : rawRates.VNDUSD;
} else if (rawRates.USD && rawRates.USD > 0) {
  // Nếu base currency là VND, rates.USD chính là tỷ giá VND -> USD
  exchangeRateUSD = rawRates.USD < 1 ? 1 / rawRates.USD : rawRates.USD;
}

// các tham số đầu vào từ Google Sheets
const totalInvested = parseFloat(sheetInput.totalInvested || 0);
const avgBuyPriceVND = parseFloat(sheetInput.avgBuyPriceVND || 0);
const investmentCycle = parseFloat(sheetInput['Investment cycle'] || sheetInput.investmentCycle || 1);

// 3. Tính toán các chỉ số theo VND & Khối lượng
const sipAmountVND = investmentCycle > 0 ? totalInvested / investmentCycle : 0;
const totalOunces = avgBuyPriceVND > 0 ? totalInvested / avgBuyPriceVND : 0;
const totalGrams = totalOunces * 31.1035;
const currentPricePerGram = goldPriceVND / 31.1035;
const currentValue = totalOunces * goldPriceVND;
const pnlAmount = currentValue - totalInvested;
const pnlPercent = totalInvested > 0 ? (pnlAmount / totalInvested) * 100 : 0;

// 4. Quy đổi sang USD (chia cho tỷ giá USD/VND thực tế)
const goldPriceUSD = goldPriceVND / exchangeRateUSD;
const avgBuyPriceUSD = avgBuyPriceVND / exchangeRateUSD;
const sipAmountUSD = sipAmountVND / exchangeRateUSD;
const totalInvestedUSD = totalInvested / exchangeRateUSD;
const currentValueUSD = currentValue / exchangeRateUSD;
const pnlAmountUSD = pnlAmount / exchangeRateUSD;
const currentPriceUSDPerGram = currentPricePerGram / exchangeRateUSD;

// 5. Trả về kết quả
return [{
  json: {
    // Đơn vị VND & Khối lượng
    totalInvested: parseFloat(totalInvested.toFixed(2)),
    sipAmountVND: parseFloat(sipAmountVND.toFixed(2)),
    goldPriceVND: parseFloat(goldPriceVND.toFixed(2)),
    avgBuyPriceVND: parseFloat(avgBuyPriceVND.toFixed(2)),
    totalOunces: parseFloat(totalOunces.toFixed(4)),
    totalGrams: parseFloat(totalGrams.toFixed(4)),
    currentPricePerGram: parseFloat(currentPricePerGram.toFixed(2)),
    currentValue: parseFloat(currentValue.toFixed(2)),
    pnlAmount: parseFloat(pnlAmount.toFixed(2)),
    pnlPercent: parseFloat(pnlPercent.toFixed(2)),

    // Đơn vị USD
    exchangeRateUSD: parseFloat(exchangeRateUSD.toFixed(2)),
    goldPriceUSD: parseFloat(goldPriceUSD.toFixed(2)),
    avgBuyPriceUSD: parseFloat(avgBuyPriceUSD.toFixed(2)),
    sipAmountUSD: parseFloat(sipAmountUSD.toFixed(2)),
    totalInvestedUSD: parseFloat(totalInvestedUSD.toFixed(2)),
    currentValueUSD: parseFloat(currentValueUSD.toFixed(2)),
    pnlAmountUSD: parseFloat(pnlAmountUSD.toFixed(2)),
    currentPriceUSDPerGram: parseFloat(currentPriceUSDPerGram.toFixed(2))
  }
}];

