// 1. Khai báo tỷ giá USD/INR và lấy các biến gốc từ Input
const exchangeRateUSD = 83; // Tỷ giá quy đổi USD/INR

const sipAmountINR = $input.item.json.sipAmountINR || 0;
const avgBuyPriceINR = $input.item.json.avgBuyPriceINR || 0;
const pnlAmount = $input.item.json.pnlAmount || 0;
const currentValue = $input.item.json.currentValue || 0;
const currentPricePerGram = $input.item.json.currentPricePerGram || 0;
const goldPriceINR = $input.item.json.goldPriceINR || 0;
const totalInvested = $input.item.json.totalInvested || 0;

// 2. Tính toán các biến USD
const sipAmountUSD = sipAmountINR / exchangeRateUSD;
const avgBuyPriceUSD = avgBuyPriceINR / exchangeRateUSD;
const pnlAmountUSD = pnlAmount / exchangeRateUSD;
const currentValueUSD = currentValue / exchangeRateUSD;
const currentPriceUSDPerGram = currentPricePerGram / exchangeRateUSD;
const goldPriceUSD = goldPriceINR / exchangeRateUSD;
const totalInvestedUSD = totalInvested / exchangeRateUSD;

